def norm(s): return re.sub(r'\s+',' ',s).strip()
def q(page,v,s,t):
    t=norm(t)
    assert t in norm(pages[page]), (page,t)
    ledger.append(dict(page=page,version=v,speaker=s,quote=t))
    return f'“{t}” ({v}, {s}, PDF p. {page})'
